def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    prev_bids = []
    pressured_opponents = 0
    rich_opponents = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= DAILY_SALARY * 8:
            rich_opponents += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            pressured_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid', 0)
            status = prev.get('status')
            err = prev.get('error')
            if err is None and status != 'error':
                prev_bids.append(float(bid))

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 85.0
        avg_prev = 80.0

    units = int(supply / WATER_REQ)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 50.0))
        return float(min(budget, 20.0))

    emergency = hp <= 2 or no_water_days >= 1
    danger = hp <= 4

    if units <= 1:
        if emergency:
            bid = max(highest_prev + 4.0, 108.0)
        elif danger:
            bid = max(highest_prev + 2.0, 98.0)
        else:
            bid = max(avg_prev + 3.0, highest_prev + 1.0, 92.0)
        if pressured_opponents >= 1:
            bid += 3.0
        if rich_opponents >= 2:
            bid += 2.0
    else:
        if emergency:
            bid = max(avg_prev, 82.0)
        elif danger:
            bid = max(avg_prev - 4.0, 72.0)
        else:
            bid = max(avg_prev - 10.0, 58.0)
        if units >= 2:
            bid -= 4.0

    if day >= 8 and hp > 4 and no_water_days == 0:
        bid -= 3.0

    if budget < 120:
        bid = min(bid, budget)
    else:
        bid = min(bid, budget, 115.0)

    if emergency and budget > 0:
        bid = max(min(budget, 112.0), bid)

    if bid < 0:
        bid = 0.0

    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    VERY_AGGRESSIVE_BID_FACTOR = 0.9
    AGGRESSIVE_BID_FACTOR = 0.75
    MODERATE_BID_FACTOR = 0.65
    CONSERVATIVE_BID_FACTOR = 0.5
    LOW_BID_FACTOR = 0.3 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * LOW_BID_FACTOR)

    CRITICAL_HP_THRESHOLD = 2 

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    current_bid = 0.0

    if my_status['hp'] <= CRITICAL_HP_THRESHOLD:
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            current_bid = max(DAILY_SALARY * AGGRESSIVE_BID_FACTOR, highest_prev_bid + 2.0)
        else:
            current_bid = DAILY_SALARY * VERY_AGGRESSIVE_BID_FACTOR
    else:
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            if highest_prev_bid >= DAILY_SALARY * AGGRESSIVE_BID_FACTOR:
                current_bid = max(DAILY_SALARY * MODERATE_BID_FACTOR, highest_prev_bid + 1.0)
            else:
                current_bid = max(DAILY_SALARY * CONSERVATIVE_BID_FACTOR, highest_prev_bid + 1.0)
        else:
            current_bid = DAILY_SALARY * MODERATE_BID_FACTOR

    current_bid = min(current_bid, my_status['budget'])
    current_bid = max(0.0, current_bid)

    return current_bid

